//========== Main Function Implementation ===========

int main(void)
{
    //    char stringBuffer[12]; // buffer pour l'envois de string convertit depuis une variable (-XXXX.Xxxxx\0)
    uint8_t affiche_modem = 254; // quelle valeurs on affiche 
    uint8_t affiche_poele = 254; // quelle valeurs on affiche
    bool afficheTemp = false; // ligne 1 : true = temperature, false = status poele

    poeleStatus_OK = false;
    modemStatus_OK = false;
    smsToSend = false;

    bool negTemp = false; // indicateur de temperature negative
    // Removed: unused variable selfTest
    Sys_Init(); // initialisation du systeme

    // preparation du LCD
    LCD_Clear();
    LCD_Cursor(LCD_CURSOR_OFF);
    LCD_BackLight(LCD_BACKLIGHT_ON);

    // indique le chargement
    LCD_Clear();
    LCD_Write_String("LOADING");

    __delay_ms(1000); // laisse une seconde pour être sur d'appuyer sur les boutons
                      // (et laisse le SCD41 demarrer : 1s apres mise sous tension)

    // demarre la mesure periodique du SCD41 (nouvelle valeur toutes les 5s)
    if (!SCD41_Init())
    {
        LCD_Clear();
        LCD_Write_String("SCD41 ERREUR");
        __delay_ms(1000);
    }

    // Enable the Global Interrupts 
    INTERRUPT_GlobalInterruptEnable();

    // Enable the Peripheral Interrupts 
    INTERRUPT_PeripheralInterruptEnable();

    // enable interrupt UART receive 
    PIE3bits.RC1IE = 1;
    PIE3bits.RC2IE = 1;

    // initialise le Modem
    SIM7600_Init();

    // indique qu'il est pret
    LCD_Clear();
    LCD_Write_String("READY");

    while (1) // boucle infinie
    {
        if (S2 == PRESS)
        {
            while (S2 == PRESS);
            Uart2SendString_modem("AT+CMGR=0\r\n");
        }

        if (S3 == PRESS)
        {
            while (S3 == PRESS);

            Uart2SendString_modem("AT+CPMS?\r\n");
        }

        if (S4 == PRESS)
        {
            while (S4 == PRESS);
            SIM7600_SendSMS("S4");
        }
        // traitements du modem hors interruption (memoire SMS pleine)
        SIM7600_Task();

        // lecture du SCD41 des qu'une nouvelle mesure est disponible (toutes les 5s)
        // LCD 2x8 : la ligne 1 alterne a chaque mesure entre temperature et status poele
        if (SCD41_DataReady())
        {
            // met a jour les valeurs utilisees par les commandes SMS (commands.c)
            if (ReadMeasurement(&co2Value, &tempValue_x10, &humidityValue))
            {
                sensorValid = true;
                afficheTemp = !afficheTemp;
                if (afficheTemp)
                {
                    LCD_Cursor_Position(1, 1);
                    LCD_Write_Temperature(tempValue_x10);
                }
                else
                {
                    affiche_poele = 0; // reaffiche le status poele tout de suite
                }
            }
        }

        // execution de commande
        if (executionFlag) // si il faut executer une commande
        {
            Execute(); // execution de la commande set avec "Command"
        }

        if (modemStatus_OK)
        {
            if (affiche_modem == 0)
            {
                LCD_Cursor_Position(2, 1);
                LCD_Write_String("MODEM OK");
                affiche_modem = 254;
            }
            affiche_modem--;
        }
        else
        {
            if (affiche_modem == 0)
            {
                LCD_Cursor_Position(2, 1);
                LCD_Write_String("MODEM KO");
                affiche_modem = 254;
            }
            affiche_modem--;
        }

        if (afficheTemp)
        {
            // ligne 1 occupee par la temperature
        }
        else if (poeleStatus_OK)
        {
            if (affiche_poele == 0)
            {
                LCD_Cursor_Position(1, 1);
                LCD_Write_String("Poele OK");
                affiche_poele = 254;
            }
            affiche_poele--;
        }
        else
        {
            if (affiche_poele == 0)
            {
                LCD_Cursor_Position(1, 1);
                LCD_Write_String("Poele KO");
                affiche_poele = 254;
            }
            affiche_poele--;
        }

        if (smsToSend)
        {
            SIM7600_SendSMS(bufferSMS);
            bufferSMS[0] = '\0';
            smsToSend = false;
            LCD_Cursor_Position(1, 1);
            LCD_Write_String(bufferSMS);
        }
    }
    while (1); // Garde-Fou  ->  Boucle infinie
}
